// jasql-goldgen builds/refreshes the golden evaluation set by selecting
// representative cases from sql_datasets.json: stratified across business
// domain and difficulty, restricted to cases whose tables and columns
// actually exist in the compiled catalog. Hand-curated entries at the top of
// the existing golden file are preserved.
//
// Usage:
//
//	go run ./cmd/jasql-goldgen -data ./data/kcb -n 80
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"jasql/internal/catalog"
)

func main() {
	var (
		dataDir string
		outPath string
		total   int
		keep    int
	)
	flag.StringVar(&dataDir, "data", filepath.Join("data", "kcb"), "Path to metadata directory")
	flag.StringVar(&outPath, "out", "", "Output path (default <data>/golden_queries.json)")
	flag.IntVar(&total, "n", 80, "Target total number of golden cases (including kept curated entries)")
	flag.IntVar(&keep, "keep", 5, "Number of leading entries of the existing golden file to preserve as curated")
	flag.Parse()
	if outPath == "" {
		outPath = filepath.Join(dataDir, "golden_queries.json")
	}

	cat, err := catalog.Load(dataDir)
	if err != nil {
		log.Fatalf("load catalog: %v", err)
	}

	var curated []catalog.GoldenQuery
	if b, err := os.ReadFile(outPath); err == nil {
		var existing []catalog.GoldenQuery
		if err := json.Unmarshal(b, &existing); err != nil {
			log.Fatalf("parse existing golden file: %v", err)
		}
		if keep > len(existing) {
			keep = len(existing)
		}
		curated = existing[:keep]
	}
	seenQuestion := map[string]bool{}
	for _, g := range curated {
		seenQuestion[normalize(g.Question)] = true
	}

	// bucket candidate samples by domain x difficulty for stratified picking
	type candidate struct {
		g        catalog.GoldenQuery
		sourceID string
	}
	buckets := map[string][]candidate{}
	skipped := map[string]int{}
	for _, s := range cat.Samples {
		q := strings.TrimSpace(s.Question)
		if q == "" || strings.TrimSpace(s.TargetSQL) == "" || seenQuestion[normalize(q)] {
			skipped["empty_or_duplicate"]++
			continue
		}
		tables, ok := resolveTables(cat, s.TargetTable)
		if !ok || len(tables) == 0 {
			skipped["unresolved_tables"]++
			continue
		}
		columns := resolveColumns(cat, s.TargetColumn, tables)
		g := catalog.GoldenQuery{
			Question:        q,
			ExpectedTables:  tables,
			ExpectedColumns: columns,
			ExpectedMetrics: cat.MetricNamesInQuestion(q),
			Note:            fmt.Sprintf("auto-generated from sql_datasets id=%v domain=%s difficulty=%s", s.ID, s.TargetDomain, s.TargetDifficulty),
		}
		// keep expected_sql only when it passes static validation, so the
		// eval's SQL-validity metric measures our validator against known-good
		// SQL instead of inheriting dataset typos.
		if v := cat.ValidateSQL(catalog.ValidateRequest{SQL: s.TargetSQL}); v.Valid {
			g.ExpectedSQL = s.TargetSQL
		}
		key := strings.TrimSpace(s.TargetDomain) + "|" + strings.TrimSpace(s.TargetDifficulty)
		buckets[key] = append(buckets[key], candidate{g: g, sourceID: fmt.Sprint(s.ID)})
	}

	// deterministic order inside buckets and across bucket keys
	keys := make([]string, 0, len(buckets))
	for k := range buckets {
		keys = append(keys, k)
		sort.SliceStable(buckets[k], func(i, j int) bool { return buckets[k][i].sourceID < buckets[k][j].sourceID })
	}
	sort.Strings(keys)

	want := total - len(curated)
	if want < 0 {
		want = 0
	}
	selected := []catalog.GoldenQuery{}
	for round := 0; len(selected) < want; round++ {
		progressed := false
		for _, k := range keys {
			if len(selected) >= want {
				break
			}
			if round < len(buckets[k]) {
				c := buckets[k][round]
				if seenQuestion[normalize(c.g.Question)] {
					continue
				}
				seenQuestion[normalize(c.g.Question)] = true
				selected = append(selected, c.g)
				progressed = true
			}
		}
		if !progressed {
			break
		}
	}

	out := append(append([]catalog.GoldenQuery{}, curated...), selected...)
	for i := range out {
		out[i].ID = i + 1
	}
	b, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		log.Fatal(err)
	}
	if err := os.WriteFile(outPath, append(b, '\n'), 0o644); err != nil {
		log.Fatal(err)
	}
	withSQL := 0
	for _, g := range out {
		if g.ExpectedSQL != "" {
			withSQL++
		}
	}
	log.Printf("wrote %s: %d cases (%d curated + %d generated from %d buckets), %d with validated expected_sql; skipped: %v",
		outPath, len(out), len(curated), len(selected), len(keys), withSQL, skipped)
}

func resolveTables(cat *catalog.Catalog, targetTable string) ([]string, bool) {
	var out []string
	seen := map[string]bool{}
	for _, raw := range strings.Split(targetTable, "|") {
		raw = strings.TrimSpace(raw)
		if raw == "" {
			continue
		}
		t, ok := cat.ResolveTable(raw)
		if !ok {
			return nil, false
		}
		if !seen[t.FQN] {
			seen[t.FQN] = true
			out = append(out, t.FQN)
		}
	}
	return out, true
}

func resolveColumns(cat *catalog.Catalog, targetColumn string, tableFQNs []string) []string {
	var out []string
	seen := map[string]bool{}
	for _, raw := range strings.Split(targetColumn, "|") {
		raw = strings.TrimSpace(raw)
		if raw == "" {
			continue
		}
		col := raw
		if i := strings.LastIndex(raw, "."); i >= 0 {
			col = raw[i+1:]
		}
		col = strings.ToUpper(strings.TrimSpace(col))
		if col == "" || seen[col] {
			continue
		}
		for _, fqn := range tableFQNs {
			if t, ok := cat.ResolveTable(fqn); ok && t.ColumnMap[col] != nil {
				seen[col] = true
				out = append(out, col)
				break
			}
		}
		if len(out) >= 6 {
			break
		}
	}
	return out
}

func normalize(s string) string {
	return strings.Join(strings.Fields(strings.ToLower(s)), " ")
}
package mcp

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"jasql/internal/catalog"
)

// newFixtureServer builds a server over a tiny sandbox data dir so dataset
// mutations never touch the real data/kcb.
func newFixtureServer(t *testing.T) (*Server, string) {
	t.Helper()
	dir := t.TempDir()
	writeFile := func(name, content string) {
		t.Helper()
		if err := os.WriteFile(filepath.Join(dir, name), []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	writeFile("meta_physical_models.json", `[
	 {"schema_name":"TS","table_name":"TBL1","column_order":"1","column_name":"CUST_NO","data_type":"VARCHAR2","length_precision":"10","is_pk":"Y","is_fk":"N","description":"테스트 테이블"},
	 {"schema_name":"TS","table_name":"TBL1","column_order":"2","column_name":"USE_AMT","data_type":"NUMBER","length_precision":"15","is_pk":"N","is_fk":"N","description":"이용금액"}
	]`)
	writeFile("meta_logical_models.json", `[
	 {"schema_name":"TS","entity_name_en":"TBL1","entity_name_ko":"테스트_고객","entity_order":"1","attribute_name_ko":"고객번호","attribute_name_en":"CUST_NO","data_type":"VARCHAR2","is_pk":"Y","is_fk":"N","description":""}
	]`)
	c, err := catalog.Load(dir)
	if err != nil {
		t.Fatalf("Load fixture: %v", err)
	}
	return NewServer(c, Options{Stateful: false}), dir
}

func callToolJSON(t *testing.T, s *Server, name, args string) (any, error) {
	t.Helper()
	params, _ := json.Marshal(map[string]any{"name": name, "arguments": json.RawMessage(args)})
	return s.callTool(t.Context(), params)
}

func TestListAndGetDatasets(t *testing.T) {
	s, _ := newFixtureServer(t)
	res, err := callToolJSON(t, s, "list_datasets", `{}`)
	if err != nil {
		t.Fatal(err)
	}
	datasets := res.(map[string]any)["datasets"].([]map[string]any)
	if len(datasets) != len(catalog.DatasetRegistry) {
		t.Fatalf("expected %d datasets, got %d", len(catalog.DatasetRegistry), len(datasets))
	}
	byName := map[string]map[string]any{}
	for _, d := range datasets {
		byName[d["name"].(string)] = d
	}
	if byName["physical_models"]["present"] != true || byName["physical_models"]["required"] != true {
		t.Fatalf("physical_models status wrong: %+v", byName["physical_models"])
	}
	if byName["glossary"]["present"] != false {
		t.Fatalf("glossary should be absent in fixture: %+v", byName["glossary"])
	}
	got, err := callToolJSON(t, s, "get_dataset", `{"name":"physical_models","sample_rows":1}`)
	if err != nil {
		t.Fatal(err)
	}
	g := got.(map[string]any)
	if g["total_entries"].(int) != 2 || len(g["sample"].([]any)) != 1 {
		t.Fatalf("unexpected sample: %+v", g)
	}
	if _, err := callToolJSON(t, s, "get_dataset", `{"name":"nope"}`); err == nil {
		t.Fatal("unknown dataset must error")
	}
}

func TestPutDatasetAppliesAndHotSwaps(t *testing.T) {
	s, dir := newFixtureServer(t)
	before := s.cat()
	res, err := callToolJSON(t, s, "put_dataset", `{"name":"glossary","content":{"entries":[{"term":"고객","synonyms":["cust","cust_no"],"category":"entity"}]}}`)
	if err != nil {
		t.Fatal(err)
	}
	r := res.(map[string]any)
	if r["applied"] != true {
		t.Fatalf("expected applied, got %+v", r)
	}
	if s.cat() == before {
		t.Fatal("catalog was not hot-swapped")
	}
	if len(s.cat().Glossary.Entries) != 1 {
		t.Fatalf("new glossary not loaded: %+v", s.cat().Glossary)
	}
	if _, err := os.Stat(filepath.Join(dir, "glossary.json")); err != nil {
		t.Fatal("glossary.json not written")
	}
	// wrong shape: glossary expects an object
	if _, err := callToolJSON(t, s, "put_dataset", `{"name":"glossary","content":[1,2]}`); err == nil || !strings.Contains(err.Error(), "JSON object") {
		t.Fatalf("expected shape error, got %v", err)
	}
