package main

import (
 \"bytes\"
 \"encoding/json\"
 \"fmt\"
 \"os\"
 \"os/exec\"
 \"path/filepath\"
 \"reflect\"
 \"strings\"
 \"testing\"

 \"jasql/internal/catalog\"
)

func TestGoldgenCLI(t *testing.T) {
 binary := filepath.Join(t.TempDir(), \"goldgen\")
 if output, err := exec.Command(\"go\", \"build\", \"-o\", binary, \".\").CombinedOutput(); err "'!= nil {
  t.Fatalf("build CLI: %v'"\\n%s\", err, output)
 }
 run := func(t *testing.T, args ...string) (string, error) {
  t.Helper()
  cmd := exec.CommandContext(t.Context(), binary, args...)
  cmd.Dir = t.TempDir()
  var stderr bytes.Buffer
  cmd.Stderr = &stderr
  err := cmd.Run()
  return stderr.String(), err
 }
 const existing = \"[\\n {\\\"id\\\":1,\\\"question\\\":\\\"curated one\\\",\\\"expected_tables\\\":[\\\"TS.TBL1\\\"],\\\"note\\\":\\\"manual\\\"},\\n {\\\"id\\\":2,\\\"question\\\":\\\"curated two\\\",\\\"expected_tables\\\":[\\\"TS.TBL1\\\"]}\\n]\\n\"
 for _, flagName := range []string{\"keep\", \"n\"} {
  for _, explicit := range []bool{false, true} {
   for _, present := range []bool{false, true} {
    for _, missingData := range []bool{false, true} {
     name := fmt.Sprintf(\"negative_%s/explicit=%t/present=%t/missingData=%t\", flagName, explicit, present, missingData)
     t.Run(name, func(t *testing.T) {
      dir := goldgenFixture(t)
      if missingData { dir = filepath.Join(t.TempDir(), \"missing\") }
      out := filepath.Join(dir, \"golden_queries.json\")
      args := []string{\"-data\", dir, \"-keep\", \"0\", \"-n\", \"0\", \"-\"+flagName, \"-1\"}
      if explicit {
       out = filepath.Join(t.TempDir(), \"output.json\")
       args = append(args, \"-out\", out)
      }
      // With default output and missing metadata, create only the output's parent.
      if present {
       if err := os.MkdirAll(filepath.Dir(out), 0o755); err "'!= nil { t.Fatal(err) }
       writeGoldgenFile(t, out, existing)
      }
      stderr, err := run(t, args...)
      if err == nil { t.Error("negative argument succeeded") }
      if !strings.Contains(stderr, "-"+flagName+" must be >= 0") { t.Errorf("missing input diagnostic: %s", stderr) }
      for _, forbidden := range []string{"panic:", "goroutine ", "load catalog:", "parse existing golden file:"} {
       if strings.Contains(stderr, forbidden) { t.Errorf("unexpected %q in stderr: %s", forbidden, stderr) }
      }
      got, readErr := os.ReadFile(out)
      if present {
       if readErr != nil || string(got) != existing { t.Errorf("existing output changed: %q, %v", got, readErr) }
      } else if !os.IsNotExist(readErr) { t.Errorf("output created or unexpected error: %q, %v", got, readErr) }
     })
    }
   }
  }
 }
 for _, tc := range []struct {
  name string
  n, keep int
  questions []string
 }{
  {"zero", 0, 0, []string{}},
  {"generate", 1, 0, []string{"generated"}},
  {"preserve_and_generate", 2, 1, []string{"curated one", "generated"}},
  {"clamp_keep", 3, 9, []string{"curated one", "curated two", "generated"}},
  {"below_preserved", 1, 2, []string{"curated one", "curated two"}},
  {"zero_with_preserved", 0, 2, []string{"curated one", "curated two"}},
 } {
  for _, explicit := range []bool{false, true} {
   t.Run(fmt.Sprintf("%s/explicit=%t", tc.name, explicit), func(t *testing.T) {
    dir := goldgenFixture(t)
    out := filepath.Join(dir, "golden_queries.json")
    args := []string{"-data", dir, "-n", fmt.Sprint(tc.n), "-keep", fmt.Sprint(tc.keep)}
    if explicit { out = filepath.Join(t.TempDir(), "output.json"); args = append(args, "-out", out) }
    writeGoldgenFile(t, out, existing)
    if stderr, err := run(t, args...); err != nil { t.Fatalf("CLI failed: %v'"\\n%s\", err, stderr) }
    b, err := os.ReadFile(out)
    if err "'!= nil { t.Fatal(err) }
    var got []catalog.GoldenQuery
    if err := json.Unmarshal(b, &got); err != nil { t.Fatal(err) }
    if got == nil { t.Fatal("expected JSON array, got null") }
    questions := []string{}
    for i, g := range got {
     questions = append(questions, g.Question)
     if g.ID != i+1 { t.Errorf("ID = %d, want %d", g.ID, i+1) }
     if !reflect.DeepEqual(g.ExpectedTables, []string{"TS.TBL1"}) { t.Errorf("tables: %v", g.ExpectedTables) }
     if g.Question == "curated one" && g.Note != "manual" { t.Errorf("curated note lost: %+v", g) }
     if g.Question == "generated" && (g.ExpectedSQL != "SELECT CUST_NO FROM TS.TBL1" || !reflect.DeepEqual(g.ExpectedColumns, []string{"CUST_NO"})) { t.Errorf("generated case: %+v", g) }
    }
    if !reflect.DeepEqual(questions, tc.questions) { t.Errorf("questions = %v, want %v", questions, tc.questions) }
   })
  }
 }
}

func writeGoldgenFile(t *testing.T, path, content string) {
 t.Helper()
 if err := os.WriteFile(path, []byte(content), 0o644); err != nil { t.Fatal(err) }
}

func goldgenFixture(t *testing.T) string {
 t.Helper()
